  $('#seedBalance').textContent=Math.floor(state.seeds);$('#rankLabel').textContent=window.innerWidth<=900?(C.MISSIONS[state.mission]?.title||'Sanctuary complete'):'Lv '+rank.level+' · '+rank.name;$('#seasonLabel').textContent=weather.season;
