function items(){if(category==='plants'){const preferred=state.biome==='desert'?['cactus','succulent','grass','flower','moss','tree']:['fern','moss','clover','flower','mushroom','tree'];return preferred.concat(C.PLANTS.filter(k=>!preferred.includes(k)));}if(category==='terrain')return['raise','lower','smooth','pond','rock','log','crystal','erase'];return C.CREATURES;}
