function nearestAt(p,max=.80){if(!p)return null;let id=null,best=max;for(const e of state.entities){const pos=world.visuals.get(e.id)?.root.position||e,d=Math.hypot(p.x-pos.x,p.z-pos.z);if(d<best){best=d;id=e.id;}}return id;}
function inspect(id){if(id==null){toast('Tap the base or leaves of an element to inspect it.');return;}inspectId=id;$('#inspector').hidden=false;document.body.classList.add('inspecting');world.focusEntity(id);refreshInspector();}
