  $('#inspectState').textContent=lost?'Revive your little world in Care':ready?'Golden seeds are ready to collect':plant?(e.health<.55?'Needs a little care':e.growth<.8?'A seedling, still growing':'A mature little life'):def.creature?'Exploring a favorite habitat':'Every small element has a part to play';
