function harvest(id=null){if(state.careMode==='pet'&&!state.careState.alive){toast('Revive your little world in Care to collect seeds again.');return;}const ready=state.entities.filter(e=>(id===null||id===e.id)&&C.isReady(e));if(!ready.length)return;snapshot();const result=C.harvest(state,id);toast('Collected '+result.seeds+' seeds from '+result.count+(result.count===1?' plant.':' plants.'));note('Harvested '+result.seeds+' seeds');handleEvents(result.events);changed();refreshUI();}
function removeEntity(id){const e=state.entities.find(e=>e.id===id);if(!e)return;snapshot();const refund=C.remove(state,id);world.removeEntity(id);if(inspectId===id)closeInspector();changed();refreshUI();toast(C.ELEMENTS[e.type].label+' removed.'+(refund?' Returned '+refund+' seeds.':''));}
