 if(ambient){ambient.context.suspend();ambient=null;$('#soundBtn').innerHTML=icon('volumeOff');$('#soundBtn').setAttribute('aria-label','Enable ambient sound');return;}
 try{if(window.verdantAudio){window.verdantAudio.context.resume();ambient=window.verdantAudio;}else{const Context=window.AudioContext||window.webkitAudioContext,context=new Context(),master=context.createGain();master.gain.value=.075;master.connect(context.destination);const notes=[130.813,195.998,261.626,293.665,391.995];for(let i=0;i<notes.length;i++){const osc=context.createOscillator(),gain=context.createGain(),lfo=context.createOscillator(),depth=context.createGain();osc.type='sine';osc.frequency.value=notes[i];gain.gain.value=.055;lfo.frequency.value=.026+i*.009;depth.gain.value=.032;lfo.connect(depth);depth.connect(gain.gain);osc.connect(gain);gain.connect(master);osc.start();lfo.start();}ambient={context};window.verdantAudio=ambient;}$('#soundBtn').innerHTML=icon('volume');$('#soundBtn').setAttribute('aria-label','Mute ambient sound');toast('A quiet little soundtrack.');}catch(e){toast('Ambient audio is unavailable in this browser.');}
